   [207]={next_id=208, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她站在桌前看着那些笔记，而窗外的极光在远处静静流淌，无声地变幻着色彩，像是和她一样在喃喃自语。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1505.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [208]={next_id=209, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="警告——检测到异常高浓度能量波动。安全程序已启动，本区域所有出口已封锁。", msg_color="", msg_size=0, talker="系统音", audio="", img="arts/ui/bg/story/storybg_1505.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [209]={next_id=210, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="下面将自动播放紧急留存记录——", msg_color="", msg_size=0, talker="系统音", audio="", img="arts/ui/bg/story/storybg_1505.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [210]={next_id=211, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="自动启动？！等等，这个安全程序不是应该需要手动才能——", msg_color="", msg_size=0, talker="涅普露", audio="", img="arts/ui/bg/story/storybg_1505.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7197", 0, 0, 65.5, 216.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
