   [255]={next_id=256, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Ђ主任让我们来找他，是因为他还相信有人可以继续下去。", msg_color="", msg_size=0, talker="涅普露", audio="", img="arts/ui/bg/story/storybg_1505.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7197", 0, 0, 65.5, 216.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [256]={next_id=257, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可他临死前告诉我们的最后一件事，是——要我离开，不要回头。", msg_color="", msg_size=0, talker="涅普露", audio="", img="arts/ui/bg/story/storybg_1505.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7197", 0, 0, 65.5, 216.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
